INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-11-16', 'phase-11-lesson-16-load-testing-foundations-closed-vs-open-s', 'module-12', 16, 'Lesson 12.16: Load Testing Foundations: Closed vs Open Systems & Little''s Law', 'Prerequisites: Phase 8, Lesson 11.1', 'Prerequisites: Phase 8, Lesson 11.1 | Subtopics: 6 items', 'Systems project application', 320, 12, 2810.0, 800.0, '# Lesson 11.16: Load Testing Foundations: Closed vs Open Systems & Little''s Law

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 8, Lesson 11.1
- **Subtopics**:
  - `11.16.1` Load testing paradigms: Closed System (fixed number of users looping; requests delayed if system slows) vs Open System
  - `11.16.2` Open System model: users arrive independently according to a Poisson process; arrival rate does not slow down when system degrades
  - `11.16.3` Why closed model load testers hide catastrophic production outages: masking queue explosions through coordinated omission
  - `11.16.4` Little''s Law: $L = \lambda W$ (Average items in system = Arrival rate $\times$ Average time in system)
  - `11.16.5` Load testing types: Smoke test (minimal load), Stress test (breaking point), Soak/Endurance test (memory leaks over 24h), Spike test
  - `11.16.6` Defining load testing targets: p95 latency $<150$ms at 5,000 QPS with $<0.01\%$ HTTP error rate
- **Key Failure Modes & Edge Cases**: Conducting load testing using a closed-loop tester that throttles itself when the server degrades, reporting misleadingly low latencies.
- **Verification & Mastery Check**: Calculate expected queue lengths and concurrency requirements for a 10,000 QPS service using Little''s Law.
- **Project Application**: ModelPulse: Load test capacity planning spreadsheet.', '{"solution.py": "# Phase 11 // Lesson 11.16: Load Testing Foundations: Closed vs Open Systems & Little''s Law\n\ndef solve():\n    \"\"\"\n    Verification: Calculate expected queue lengths and concurrency requirements for a 10,000 QPS service using Little''\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.16", "subtopics_count": 6, "verification_criteria": "Calculate expected queue lengths and concurrency requirements for a 10,000 QPS service using Little''s Law.", "subtopics": ["11.16.1 Load testing paradigms: Closed System (fixed number of users looping; requests delayed if system slows) vs Open System", "11.16.2 Open System model: users arrive independently according to a Poisson process; arrival rate does not slow down when system degrades", "11.16.3 Why closed model load testers hide catastrophic production outages: masking queue explosions through coordinated omission", "11.16.4 Little''s Law: $L = \\lambda W$ (Average items in system = Arrival rate $\\times$ Average time in system)", "11.16.5 Load testing types: Smoke test (minimal load), Stress test (breaking point), Soak/Endurance test (memory leaks over 24h), Spike test", "11.16.6 Defining load testing targets: p95 latency $<150$ms at 5,000 QPS with $<0.01\\%$ HTTP error rate"]}'::jsonb, '["Explain how this implementation prevents: Conducting load testing using a closed-loop tester that throttles itself when the server degrades, reporting misleadingl", "How does Load Testing Foundations: Closed vs Open Systems & Little''s Law scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-17', 'phase-11-lesson-17-modern-load-testing-with-k6-javascript-sc', 'module-12', 17, 'Lesson 12.17: Modern Load Testing with k6: JavaScript Scripting & Virtual Users', 'Prerequisites: Lesson 11.16', 'Prerequisites: Lesson 11.16 | Subtopics: 6 items', 'Systems project application', 320, 12, 2870.0, 850.0, '# Lesson 11.17: Modern Load Testing with k6: JavaScript Scripting & Virtual Users

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 11.16
- **Subtopics**:
  - `11.17.1` k6 engine architecture: Go-based multi-threaded execution engine with embedded JavaScript (Goja) runtime for test scripts
  - `11.17.2` Writing k6 scripts: Virtual Users (VUs), `setup()`, default function, `teardown()`, and lifecycle stages
  - `11.17.3` Execution scenarios: configuring ramping VUs, constant VUs, ramping arrival rate (open model), and constant arrival rate
  - `11.17.4` Custom metrics: Counters, Gauges, Rates, and Trends; defining thresholds (`thresholds: { ''http_req_duration'': [''p(95)<200''] }`)
  - `11.17.5` Checks vs Thresholds: verifying functional response correctness without halting tests vs failing CI builds on SLA violations
  - `11.17.6` Data-driven testing: parameterizing tests with real CSV/JSON user credentials, unique search queries, and realistic payloads
- **Key Failure Modes & Edge Cases**: Writing k6 scripts that execute heavy synchronous computational loops inside the VU iteration, choking the load generator''s own CPU.
- **Verification & Mastery Check**: Write a modular k6 load testing suite simulating an e-commerce checkout flow with ramping arrival rate and strict p95 latency thresholds.
- **Project Application**: ModelPulse: Automated k6 load testing suite.', '{"solution.py": "# Phase 11 // Lesson 11.17: Modern Load Testing with k6: JavaScript Scripting & Virtual Users\n\ndef solve():\n    \"\"\"\n    Verification: Write a modular k6 load testing suite simulating an e-commerce checkout flow with ramping arrival ra\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.17", "subtopics_count": 6, "verification_criteria": "Write a modular k6 load testing suite simulating an e-commerce checkout flow with ramping arrival rate and strict p95 latency thresholds.", "subtopics": ["11.17.1 k6 engine architecture: Go-based multi-threaded execution engine with embedded JavaScript (Goja) runtime for test scripts", "11.17.2 Writing k6 scripts: Virtual Users (VUs), `setup()`, default function, `teardown()`, and lifecycle stages", "11.17.3 Execution scenarios: configuring ramping VUs, constant VUs, ramping arrival rate (open model), and constant arrival rate", "11.17.4 Custom metrics: Counters, Gauges, Rates, and Trends; defining thresholds (`thresholds: { ''http_req_duration'': [''p(95)<200''] }`)", "11.17.5 Checks vs Thresholds: verifying functional response correctness without halting tests vs failing CI builds on SLA violations", "11.17.6 Data-driven testing: parameterizing tests with real CSV/JSON user credentials, unique search queries, and realistic payloads"]}'::jsonb, '["Explain how this implementation prevents: Writing k6 scripts that execute heavy synchronous computational loops inside the VU iteration, choking the load generato", "How does Modern Load Testing with k6: JavaScript Scripting & Virtual Users scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-18', 'phase-11-lesson-18-distributed-load-testing-locust-cloud-sca', 'module-12', 18, 'Lesson 12.18: Distributed Load Testing: Locust & Cloud-Scale Traffic Injection', 'Prerequisites: Lesson 11.16, Lesson 11.17', 'Prerequisites: Lesson 11.16, Lesson 11.17 | Subtopics: 6 items', 'Systems project application', 320, 12, 2750.0, 900.0, '# Lesson 11.18: Distributed Load Testing: Locust & Cloud-Scale Traffic Injection

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 11.16, Lesson 11.17
- **Subtopics**:
  - `11.18.1` Single-node load generator limits: network socket exhaustion (ephemeral port limits), client CPU saturation, and bandwidth ceilings
  - `11.18.2` Locust architecture: Python-based load testing framework with gevent coroutines; Master-Worker distributed topology
  - `11.18.3` Master node role: aggregating metrics, coordinating worker start/stop, and serving web UI dashboard
  - `11.18.4` Worker nodes role: executing greenlets injecting traffic against target systems across multiple VMs or Kubernetes pods
  - `11.18.5` Customizing traffic behavior in Locust: `FastHttpUser` (geventhttpclient) for $5\times$ higher throughput than standard `HttpUser`
  - `11.18.6` Running cloud-scale tests: deploying 50 Locust workers in Kubernetes to inject 200,000 QPS against target infrastructure
- **Key Failure Modes & Edge Cases**: Running distributed load tests from inside the same Kubernetes cluster as the target, bypassing realistic cloud ingress and firewalls.
- **Verification & Mastery Check**: Deploy a distributed Locust load testing cluster on Kubernetes with 1 master and 10 workers; generate 50,000 QPS against a test target.
- **Project Application**: ModelPulse: Distributed cloud-scale load testing harness.', '{"solution.py": "# Phase 11 // Lesson 11.18: Distributed Load Testing: Locust & Cloud-Scale Traffic Injection\n\ndef solve():\n    \"\"\"\n    Verification: Deploy a distributed Locust load testing cluster on Kubernetes with 1 master and 10 workers; generat\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.18", "subtopics_count": 6, "verification_criteria": "Deploy a distributed Locust load testing cluster on Kubernetes with 1 master and 10 workers; generate 50,000 QPS against a test target.", "subtopics": ["11.18.1 Single-node load generator limits: network socket exhaustion (ephemeral port limits), client CPU saturation, and bandwidth ceilings", "11.18.2 Locust architecture: Python-based load testing framework with gevent coroutines; Master-Worker distributed topology", "11.18.3 Master node role: aggregating metrics, coordinating worker start/stop, and serving web UI dashboard", "11.18.4 Worker nodes role: executing greenlets injecting traffic against target systems across multiple VMs or Kubernetes pods", "11.18.5 Customizing traffic behavior in Locust: `FastHttpUser` (geventhttpclient) for $5\\times$ higher throughput than standard `HttpUser`", "11.18.6 Running cloud-scale tests: deploying 50 Locust workers in Kubernetes to inject 200,000 QPS against target infrastructure"]}'::jsonb, '["Explain how this implementation prevents: Running distributed load tests from inside the same Kubernetes cluster as the target, bypassing realistic cloud ingress ", "How does Distributed Load Testing: Locust & Cloud-Scale Traffic Injection scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-19', 'phase-11-lesson-19-network-kernel-tuning-for-high-concurrenc', 'module-12', 19, 'Lesson 12.19: Network & Kernel Tuning for High-Concurrency Systems', 'Prerequisites: Phase 0, Lesson 11.16', 'Prerequisites: Phase 0, Lesson 11.16 | Subtopics: 6 items', 'Systems project application', 320, 12, 2810.0, 950.0, '# Lesson 11.19: Network & Kernel Tuning for High-Concurrency Systems

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Lesson 11.16
- **Subtopics**:
  - `11.19.1` Linux socket buffers: `rmem_max`, `wmem_max`, `tcp_rmem`, and `tcp_wmem` auto-tuning for high bandwidth-delay products
  - `11.19.2` File descriptor limits: configuring `nofile` limits in `/etc/security/limits.conf` and `fs.file-max` for 100,000+ open sockets
  - `11.19.3` TCP connection queues: SYN backlog (`tcp_max_syn_backlog`) and accept queue (`net.core.somaxconn`) preventing dropped handshakes
  - `11.19.4` Ephemeral port exhaustion: tuning `net.ipv4.ip_local_port_range` ($1024-65535$) and `tcp_tw_reuse` for high outbound connection rates
  - `11.19.5` TCP TIME_WAIT state mechanics: 2MSL (Maximum Segment Lifetime) delay; why reusing sockets safely requires timestamp support
  - `11.19.6` TCP Congestion Control algorithms: CUBIC (loss-based) vs Google BBR (Bottleneck Bandwidth and RTT-based) for high throughput
- **Key Failure Modes & Edge Cases**: Dropping client connections during load spikes because the Linux `somaxconn` listen backlog remained at the default 128.
- **Verification & Mastery Check**: Apply kernel `sysctl` network hardening configurations; verify that a server accepts 50,000 concurrent persistent TCP connections.
- **Project Application**: ModelPulse: Linux kernel network tuning automation script.', '{"solution.py": "# Phase 11 // Lesson 11.19: Network & Kernel Tuning for High-Concurrency Systems\n\ndef solve():\n    \"\"\"\n    Verification: Apply kernel `sysctl` network hardening configurations; verify that a server accepts 50,000 concurre\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.19", "subtopics_count": 6, "verification_criteria": "Apply kernel `sysctl` network hardening configurations; verify that a server accepts 50,000 concurrent persistent TCP connections.", "subtopics": ["11.19.1 Linux socket buffers: `rmem_max`, `wmem_max`, `tcp_rmem`, and `tcp_wmem` auto-tuning for high bandwidth-delay products", "11.19.2 File descriptor limits: configuring `nofile` limits in `/etc/security/limits.conf` and `fs.file-max` for 100,000+ open sockets", "11.19.3 TCP connection queues: SYN backlog (`tcp_max_syn_backlog`) and accept queue (`net.core.somaxconn`) preventing dropped handshakes", "11.19.4 Ephemeral port exhaustion: tuning `net.ipv4.ip_local_port_range` ($1024-65535$) and `tcp_tw_reuse` for high outbound connection rates", "11.19.5 TCP TIME_WAIT state mechanics: 2MSL (Maximum Segment Lifetime) delay; why reusing sockets safely requires timestamp support", "11.19.6 TCP Congestion Control algorithms: CUBIC (loss-based) vs Google BBR (Bottleneck Bandwidth and RTT-based) for high throughput"]}'::jsonb, '["Explain how this implementation prevents: Dropping client connections during load spikes because the Linux `somaxconn` listen backlog remained at the default 128.", "How does Network & Kernel Tuning for High-Concurrency Systems scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-20', 'phase-11-lesson-20-chaos-load-testing-blameless-failure-inje', 'module-12', 20, 'Lesson 12.20: Chaos Load Testing: Blameless Failure Injection under High Traffic', 'Prerequisites: Phase 7, Lesson 11.17', 'Prerequisites: Phase 7, Lesson 11.17 | Subtopics: 6 items', 'Systems project application', 320, 12, 2870.0, 1000.0, '# Lesson 11.20: Chaos Load Testing: Blameless Failure Injection under High Traffic

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 7, Lesson 11.17
- **Subtopics**:
  - `11.20.1` The objective of Chaos Load Testing: verifying that systems maintain SLAs and fail gracefully when components crash under peak load
  - `11.20.2` Combining load generators with chaos injectors: running sustained 20,000 QPS load while injecting simulated infrastructure faults
  - `11.20.3` Chaos injection scenarios: terminating primary database pods, injecting 200ms network latency to external payment gateways, killing random worker nodes
  - `11.20.4` Verifying system resilience properties: testing whether circuit breakers trip, read-replicas take over, and fallback caches engage
  - `11.20.5` Monitoring steady-state health: tracking error rates and user experience continuity throughout the chaos event
  - `11.20.6` Automated verification assertions: asserting that error rate remains $<0.5\%$ and 0 orphaned transactions linger in database
- **Key Failure Modes & Edge Cases**: Injecting chaos faults without a continuous active load test, failing to uncover race conditions that only manifest under concurrent load.
- **Verification & Mastery Check**: Execute a synchronized k6 load test while terminating the primary database replica; prove zero data corruption and self-healing under load.
- **Project Application**: ModelPulse: Automated chaos load testing verification suite.', '{"solution.py": "# Phase 11 // Lesson 11.20: Chaos Load Testing: Blameless Failure Injection under High Traffic\n\ndef solve():\n    \"\"\"\n    Verification: Execute a synchronized k6 load test while terminating the primary database replica; prove zero data \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.20", "subtopics_count": 6, "verification_criteria": "Execute a synchronized k6 load test while terminating the primary database replica; prove zero data corruption and self-healing under load.", "subtopics": ["11.20.1 The objective of Chaos Load Testing: verifying that systems maintain SLAs and fail gracefully when components crash under peak load", "11.20.2 Combining load generators with chaos injectors: running sustained 20,000 QPS load while injecting simulated infrastructure faults", "11.20.3 Chaos injection scenarios: terminating primary database pods, injecting 200ms network latency to external payment gateways, killing random worker nodes", "11.20.4 Verifying system resilience properties: testing whether circuit breakers trip, read-replicas take over, and fallback caches engage", "11.20.5 Monitoring steady-state health: tracking error rates and user experience continuity throughout the chaos event", "11.20.6 Automated verification assertions: asserting that error rate remains $<0.5\\%$ and 0 orphaned transactions linger in database"]}'::jsonb, '["Explain how this implementation prevents: Injecting chaos faults without a continuous active load test, failing to uncover race conditions that only manifest unde", "How does Chaos Load Testing: Blameless Failure Injection under High Traffic scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-21', 'phase-11-lesson-21-mlops-foundations-the-ml-lifecycle-techni', 'module-12', 21, 'Lesson 12.21: MLOps Foundations: The ML Lifecycle & Technical Debt in AI Systems', 'Prerequisites: Phase 9, Phase 10', 'Prerequisites: Phase 9, Phase 10 | Subtopics: 6 items', 'Systems project application', 320, 12, 2750.0, 1050.0, '# Lesson 11.21: MLOps Foundations: The ML Lifecycle & Technical Debt in AI Systems

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 9, Phase 10
- **Subtopics**:
  - `11.21.1` The Hidden Technical Debt in Machine Learning Systems (Sculley et al.): ML code as a small fraction of real-world ML systems
  - `11.21.2` The ML lifecycle: Data Ingestion $\to$ Feature Engineering $\to$ Model Training $\to$ Evaluation $\to$ Registry $\to$ Deployment $\to$ Monitoring
  - `11.21.3` Reproducibility in MLOps: tracking the exact triplet of (Code Version, Data Version, Hyperparameters) for every trained model
  - `11.21.4` Configuration debt, pipeline jungles, dead experimental code branches, and boundary erosion in ML architectures
  - `11.21.5` Data versioning with DVC (Data Version Control): Git-like tracking of multi-gigabyte datasets using S3/GCS content hashes
  - `11.21.6` Automating the training pipeline: orchestrating end-to-end reproducible training jobs via Kubeflow Pipelines or GitHub Actions
- **Key Failure Modes & Edge Cases**: Deploying a high-performing model to production without recording its exact training commit hash or dataset snapshot, making retraining impossible.
- **Verification & Mastery Check**: Set up DVC tracking a 5GB dataset in Google Cloud Storage; link dataset version commit tags directly to a training script run.
- **Project Application**: ModelPulse: Dataset versioning and DVC pipeline.', '{"solution.py": "# Phase 11 // Lesson 11.21: MLOps Foundations: The ML Lifecycle & Technical Debt in AI Systems\n\ndef solve():\n    \"\"\"\n    Verification: Set up DVC tracking a 5GB dataset in Google Cloud Storage; link dataset version commit tags directly\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.21", "subtopics_count": 6, "verification_criteria": "Set up DVC tracking a 5GB dataset in Google Cloud Storage; link dataset version commit tags directly to a training script run.", "subtopics": ["11.21.1 The Hidden Technical Debt in Machine Learning Systems (Sculley et al.): ML code as a small fraction of real-world ML systems", "11.21.2 The ML lifecycle: Data Ingestion $\\to$ Feature Engineering $\\to$ Model Training $\\to$ Evaluation $\\to$ Registry $\\to$ Deployment $\\to$ Monitoring", "11.21.3 Reproducibility in MLOps: tracking the exact triplet of (Code Version, Data Version, Hyperparameters) for every trained model", "11.21.4 Configuration debt, pipeline jungles, dead experimental code branches, and boundary erosion in ML architectures", "11.21.5 Data versioning with DVC (Data Version Control): Git-like tracking of multi-gigabyte datasets using S3/GCS content hashes", "11.21.6 Automating the training pipeline: orchestrating end-to-end reproducible training jobs via Kubeflow Pipelines or GitHub Actions"]}'::jsonb, '["Explain how this implementation prevents: Deploying a high-performing model to production without recording its exact training commit hash or dataset snapshot, ma", "How does MLOps Foundations: The ML Lifecycle & Technical Debt in AI Systems scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-22', 'phase-11-lesson-22-model-registries-artifact-versioning-with', 'module-12', 22, 'Lesson 12.22: Model Registries & Artifact Versioning with MLflow', 'Prerequisites: Lesson 11.21', 'Prerequisites: Lesson 11.21 | Subtopics: 6 items', 'Systems project application', 320, 12, 2810.0, 1100.0, '# Lesson 11.22: Model Registries & Artifact Versioning with MLflow

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 11.21
- **Subtopics**:
  - `11.22.1` MLflow architecture: MLflow Tracking (metrics/params), MLflow Models (standard packaging), and MLflow Model Registry
  - `11.22.2` Logging training runs: `mlflow.log_params()`, `mlflow.log_metrics()`, and logging training curves over epochs
  - `11.22.3` Model packaging: MLmodel format, Conda/Pip environment specifications, and universal pyfunc Python flavor
  - `11.22.4` Model Registry lifecycle: transitioning model versions across stages (`None` $\to$ `Staging` $\to$ `Production` $\to$ `Archived`)
  - `11.22.5` Model governance: assigning model descriptions, tagging accuracy metrics, tracking author provenance, and approval workflows
  - `11.22.6` Automated model promotion: promoting a candidate model to `Production` stage only if validation metrics exceed current production champion
- **Key Failure Modes & Edge Cases**: Deploying raw model weights without tracking dependencies, causing runtime import crashes due to mismatched library versions in production.
- **Verification & Mastery Check**: Deploy a central MLflow tracking server backed by PostgreSQL and GCS; log training runs and automate model promotion via Python SDK.
- **Project Application**: ModelPulse: Enterprise MLflow model registry infrastructure.', '{"solution.py": "# Phase 11 // Lesson 11.22: Model Registries & Artifact Versioning with MLflow\n\ndef solve():\n    \"\"\"\n    Verification: Deploy a central MLflow tracking server backed by PostgreSQL and GCS; log training runs and automate\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.22", "subtopics_count": 6, "verification_criteria": "Deploy a central MLflow tracking server backed by PostgreSQL and GCS; log training runs and automate model promotion via Python SDK.", "subtopics": ["11.22.1 MLflow architecture: MLflow Tracking (metrics/params), MLflow Models (standard packaging), and MLflow Model Registry", "11.22.2 Logging training runs: `mlflow.log_params()`, `mlflow.log_metrics()`, and logging training curves over epochs", "11.22.3 Model packaging: MLmodel format, Conda/Pip environment specifications, and universal pyfunc Python flavor", "11.22.4 Model Registry lifecycle: transitioning model versions across stages (`None` $\\to$ `Staging` $\\to$ `Production` $\\to$ `Archived`)", "11.22.5 Model governance: assigning model descriptions, tagging accuracy metrics, tracking author provenance, and approval workflows", "11.22.6 Automated model promotion: promoting a candidate model to `Production` stage only if validation metrics exceed current production champion"]}'::jsonb, '["Explain how this implementation prevents: Deploying raw model weights without tracking dependencies, causing runtime import crashes due to mismatched library vers", "How does Model Registries & Artifact Versioning with MLflow scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-23', 'phase-11-lesson-23-high-performance-model-serving-triton-vll', 'module-12', 23, 'Lesson 12.23: High-Performance Model Serving: Triton, vLLM & TorchServe', 'Prerequisites: Phase 9, Phase 10', 'Prerequisites: Phase 9, Phase 10 | Subtopics: 6 items', 'Systems project application', 320, 12, 2870.0, 1150.0, '# Lesson 11.23: High-Performance Model Serving: Triton, vLLM & TorchServe

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 9, Phase 10
- **Subtopics**:
  - `11.23.1` The model serving challenge: optimizing GPU utilization, memory bandwidth, latency, and throughput during inference
  - `11.23.2` Triton Inference Server (NVIDIA): multi-framework support (PyTorch, ONNX, TensorRT), dynamic batching, concurrent model execution
  - `11.23.3` Dynamic Batching mechanics: aggregating individual incoming requests into a single GPU tensor batch within a small time window (e.g. 5ms)
  - `11.23.4` vLLM engine internals: high-throughput LLM serving via PagedAttention (managing KV-cache memory like virtual memory pages)
  - `11.23.5` Continuous batching (iteration-level scheduling): scheduling new requests at every token generation step rather than waiting for full sequences
  - `11.23.6` Benchmarking model serving: measuring Time To First Token (TTFT), Inter-Token Latency (ITL), and Requests Per Second (RPS)
- **Key Failure Modes & Edge Cases**: Serving PyTorch models using naive Flask/FastAPI processes with concurrency=1, underutilizing expensive $30,000 GPUs by 90%.
- **Verification & Mastery Check**: Deploy an LLM using vLLM with PagedAttention; benchmark throughput against a naive HuggingFace baseline, demonstrating $4\times$ speedup.
- **Project Application**: ModelPulse: High-performance model serving deployment.', '{"solution.py": "# Phase 11 // Lesson 11.23: High-Performance Model Serving: Triton, vLLM & TorchServe\n\ndef solve():\n    \"\"\"\n    Verification: Deploy an LLM using vLLM with PagedAttention; benchmark throughput against a naive HuggingFace basel\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "11.23", "subtopics_count": 6, "verification_criteria": "Deploy an LLM using vLLM with PagedAttention; benchmark throughput against a naive HuggingFace baseline, demonstrating $4\\times$ speedup.", "subtopics": ["11.23.1 The model serving challenge: optimizing GPU utilization, memory bandwidth, latency, and throughput during inference", "11.23.2 Triton Inference Server (NVIDIA): multi-framework support (PyTorch, ONNX, TensorRT), dynamic batching, concurrent model execution", "11.23.3 Dynamic Batching mechanics: aggregating individual incoming requests into a single GPU tensor batch within a small time window (e.g. 5ms)", "11.23.4 vLLM engine internals: high-throughput LLM serving via PagedAttention (managing KV-cache memory like virtual memory pages)", "11.23.5 Continuous batching (iteration-level scheduling): scheduling new requests at every token generation step rather than waiting for full sequences", "11.23.6 Benchmarking model serving: measuring Time To First Token (TTFT), Inter-Token Latency (ITL), and Requests Per Second (RPS)"]}'::jsonb, '["Explain how this implementation prevents: Serving PyTorch models using naive Flask/FastAPI processes with concurrency=1, underutilizing expensive $30,000 GPUs by ", "How does High-Performance Model Serving: Triton, vLLM & TorchServe scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-11-24', 'phase-11-lesson-24-model-serialization-optimization-onnx-ten', 'module-12', 24, 'Lesson 12.24: Model Serialization & Optimization: ONNX, TensorRT & Quantization', 'Prerequisites: Phase 9, Lesson 11.23', 'Prerequisites: Phase 9, Lesson 11.23 | Subtopics: 6 items', 'Systems project application', 320, 12, 2750.0, 1200.0, '# Lesson 11.24: Model Serialization & Optimization: ONNX, TensorRT & Quantization

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 9, Lesson 11.23
- **Subtopics**:
  - `11.24.1` Open Neural Network Exchange (ONNX): open format representing computational graphs independently of source framework
  - `11.24.2` Exporting PyTorch models to ONNX: tracing (`torch.onnx.export`) vs script-based export, dynamic axes handling
  - `11.24.3` Graph optimization with TensorRT: layer fusion (fusing Conv+BatchNorm+ReLU into single kernel), kernel auto-tuning for specific GPU
  - `11.24.4` Quantization paradigms: Post-Training Quantization (PTQ) vs Quantization-Aware Training (QAT)
  - `11.24.5` INT8 quantization mechanics: symmetric vs asymmetric quantization, calibration datasets, and computing scaling factors
  - `11.24.6` FP8 and 4-bit quantization (AWQ, GPTQ): compressing large language models for high-throughput edge and data-center inference
- **Key Failure Modes & Edge Cases**: Exporting ONNX models with fixed batch sizes and sequence lengths, causing runtime failures when serving variable-length production requests.
- **Verification & Mastery Check**: Export a PyTorch transformer model to ONNX, optimize with TensorRT/ONNX Runtime, and measure $3\times$ latency reduction at identical accuracy.
